var w = $("#" + id);
var _plans = [];
var _steps = [];
var _reviews = [];
var _agents = {};
var _rowAuthors = {};
var _filter = "active";
var _selectedPlanId = null;

var PLAN_BUNDLE = "io.bundle.aquameta.plan";
var PLAN_COLORS = { draft: "grey", active: "blue", completed: "green", complete: "green", archived: "grey", abandoned: "grey" };
var STEP_COLORS = { pending: "yellow", active: "blue", claimed: "blue", completed: "green", complete: "green", blocked: "red", deferred: "orange", abandoned: "grey", cancelled: "grey", changes_requested: "orange" };

function val(row, field) {
    if (!row) return null;
    return typeof row.get === "function" ? row.get(field) : row[field];
}

function asArray(rows) {
    if (!rows) return [];
    if (Array.isArray(rows)) return rows;
    var out = [];
    if (typeof rows.forEach === "function") {
        rows.forEach(function(row) { out.push(row); });
        return out;
    }
    return out;
}

function esc(value) {
    return $("<div>").text(value == null ? "" : String(value)).html();
}

function dateText(value) {
    if (!value) return "-";
    var d = new Date(value);
    if (isNaN(d.getTime())) return "-";
    return d.toISOString().slice(0, 10);
}

function statusLabel(status, colors) {
    status = status || "unknown";
    var color = colors[status] || "grey";
    return '<span class="ui tiny ' + color + ' label">' + esc(status) + '</span>';
}

function rowKey(schema, relation, id) {
    return schema + "." + relation + ":" + id;
}

function jsonbArray(value) {
    if (!value) return [];
    if (Array.isArray(value)) return value;
    if (typeof value === "string") {
        try {
            var parsed = JSON.parse(value);
            return Array.isArray(parsed) ? parsed : [];
        } catch (e) {
            return [];
        }
    }
    return [];
}

function authorName(info) {
    if (!info) return "unknown";
    return info.name || info.email || "unknown";
}

function authorLine(action, info, fallbackDate) {
    var date = info && info.time ? info.time : fallbackDate;
    return action + " by " + authorName(info) + (date ? " on " + dateText(date) : "");
}

function reviewAuthorName(review) {
    return _agents[val(review, "reviewer_id")] || authorName(_rowAuthors[rowKey("companion", "plan_review", val(review, "id"))]);
}

function buildRowAuthors(commits) {
    _rowAuthors = {};
    asArray(commits).sort(function(a, b) {
        var at = val(a, "commit_time") || "";
        var bt = val(b, "commit_time") || "";
        if (at < bt) return -1;
        if (at > bt) return 1;
        return 0;
    }).forEach(function(commit) {
        jsonbArray(val(commit, "jsonb_rows")).forEach(function(rowId) {
            var pk = rowId.pk_values || [];
            var id = pk[0];
            if (!id || !rowId.schema_name || !rowId.relation_name) return;
            var key = rowKey(rowId.schema_name, rowId.relation_name, id);
            if (!_rowAuthors[key]) {
                _rowAuthors[key] = {
                    name: val(commit, "author_name"),
                    email: val(commit, "author_email"),
                    time: val(commit, "commit_time"),
                    message: val(commit, "message")
                };
            }
        });
    });
}

function isComplete(status) {
    return status === "complete" || status === "completed";
}

function isBlocked(step) {
    return val(step, "status") === "blocked" || val(step, "is_blocked") === true || val(step, "latest_review_outcome") === "blocked";
}

function stepsFor(planId) {
    return _steps.filter(function(step) { return val(step, "plan_id") === planId; }).sort(function(a, b) {
        return (val(a, "position") || 0) - (val(b, "position") || 0);
    });
}

function planReviews(planId) {
    return _reviews.filter(function(review) {
        return val(review, "plan_id") === planId && !val(review, "plan_step_id");
    }).sort(function(a, b) {
        var at = val(a, "created_at") || "";
        var bt = val(b, "created_at") || "";
        if (at < bt) return 1;
        if (at > bt) return -1;
        return 0;
    });
}

function planStats(planId) {
    var steps = stepsFor(planId);
    var complete = steps.filter(function(step) { return isComplete(val(step, "status")); }).length;
    var blocked = steps.filter(isBlocked).length;
    return { total: steps.length, complete: complete, blocked: blocked, percent: steps.length ? Math.round((complete / steps.length) * 100) : 0 };
}

function filteredPlans() {
    return _plans.filter(function(plan) {
        return _filter === "" || val(plan, "status") === _filter;
    }).sort(function(a, b) {
        var au = val(a, "updated_at") || val(a, "created_at") || "";
        var bu = val(b, "updated_at") || val(b, "created_at") || "";
        if (au < bu) return 1;
        if (au > bu) return -1;
        return 0;
    });
}

function ensureSelection(plans) {
    if (plans.length === 0) {
        _selectedPlanId = null;
        return;
    }
    var selectedStillVisible = plans.some(function(plan) { return val(plan, "id") === _selectedPlanId; });
    if (!_selectedPlanId || !selectedStillVisible) {
        _selectedPlanId = val(plans[0], "id");
    }
}

function renderPlanList(plans) {
    var list = w.find(".plan-list").empty();
    plans.forEach(function(plan) {
        var planId = val(plan, "id");
        var stats = planStats(planId);
        var active = planId === _selectedPlanId ? " active" : "";
        var planAuthor = _rowAuthors[rowKey("companion", "plan", planId)];
        list.append(
            '<button class="plan-item' + active + '" data-id="' + esc(planId) + '">' +
                '<div class="plan-item-title">' + esc(val(plan, "title")) + '</div>' +
                '<div class="plan-item-meta"><span>' + statusLabel(val(plan, "status"), PLAN_COLORS) + '</span><span>' + stats.complete + '/' + stats.total + '</span></div>' +
                '<div class="plan-item-author">' + esc(authorLine("Created", planAuthor, val(plan, "created_at"))) + '</div>' +
                '<div class="plan-progress"><div class="plan-progress-bar" style="width:' + stats.percent + '%"></div></div>' +
            '</button>'
        );
    });
}

function renderPlanReviews(planId) {
    var reviews = planReviews(planId);
    var list = w.find(".plan-review-list").empty();
    if (reviews.length === 0) {
        w.find(".no-reviews").show();
        return;
    }
    w.find(".no-reviews").hide();
    reviews.forEach(function(review) {
        list.append(
            '<div class="plan-review-item">' +
                '<div>' + statusLabel(val(review, "outcome"), STEP_COLORS) + '</div>' +
                '<div class="review-attribution">' + esc("Reviewed by " + reviewAuthorName(review) + " on " + dateText(val(review, "created_at"))) + '</div>' +
                '<div class="review-text">' + esc(val(review, "review_text") || "") + '</div>' +
            '</div>'
        );
    });
}

function renderSelectedPlan() {
    var plan = _plans.filter(function(p) { return val(p, "id") === _selectedPlanId; })[0];
    if (!plan) {
        w.find(".selected-plan").hide();
        w.find(".empty-plan").show();
        return;
    }

    var planId = val(plan, "id");
    var steps = stepsFor(planId);
    var stats = planStats(planId);
    var planAuthor = _rowAuthors[rowKey("companion", "plan", planId)];

    w.find(".empty-plan").hide();
    w.find(".selected-plan").show();
    w.find(".selected-title").text(val(plan, "title") || "Untitled plan");
    w.find(".selected-attribution").text(authorLine("Created", planAuthor, val(plan, "created_at")));
    w.find(".selected-description").text(val(plan, "description") || "");
    w.find(".selected-status").html(statusLabel(val(plan, "status"), PLAN_COLORS));
    w.find(".metric-total").text(stats.total);
    w.find(".metric-complete").text(stats.complete);
    w.find(".metric-blocked").text(stats.blocked);
    renderPlanReviews(planId);

    var body = w.find(".step-body").empty();
    if (steps.length === 0) {
        w.find(".steps-table").hide();
        w.find(".no-steps").show();
        return;
    }

    w.find(".no-steps").hide();
    w.find(".steps-table").show();
    steps.forEach(function(step) {
        var stepId = val(step, "id");
        var stepAuthor = _rowAuthors[rowKey("companion", "plan_step", stepId)];
        var agentName = _agents[val(step, "agent_id")] || "-";
        var claimed = val(step, "claimed_at") ? '<div class="step-attribution">Claimed on ' + esc(dateText(val(step, "claimed_at"))) + '</div>' : '';
        var review = val(step, "latest_review_outcome") ? statusLabel(val(step, "latest_review_outcome"), STEP_COLORS) : "-";
        var latestReviewer = val(step, "latest_reviewer");
        if (latestReviewer) {
            review += '<div class="review-attribution">by ' + esc(latestReviewer) + '</div>';
        }
        var reviewText = val(step, "latest_review_text");
        if (reviewText) {
            review += '<div class="review-note">' + esc(reviewText) + '</div>';
        }
        var result = val(step, "result") ? '<div class="step-result">Result: ' + esc(val(step, "result")) + '</div>' : '';

        body.append(
            '<tr>' +
                '<td class="step-number">' + esc(val(step, "position")) + '</td>' +
                '<td><div class="step-title">' + esc(val(step, "title")) + '</div><div class="step-attribution">' + esc(authorLine("Created", stepAuthor, val(step, "created_at"))) + '</div><div class="step-detail">' + esc(val(step, "detail") || "") + '</div>' + result + '</td>' +
                '<td>' + statusLabel(val(step, "status"), STEP_COLORS) + '</td>' +
                '<td>' + esc(agentName) + claimed + '</td>' +
                '<td>' + review + '</td>' +
            '</tr>'
        );
    });
}

function render() {
    var plans = filteredPlans();
    ensureSelection(plans);
    w.find(".plan-summary").text(plans.length + " of " + _plans.length + " plans");

    if (plans.length === 0) {
        w.find(".plan-layout").hide();
        w.find(".no-plans").show();
        return;
    }

    w.find(".no-plans").hide();
    w.find(".plan-layout").show();
    renderPlanList(plans);
    renderSelectedPlan();
}

function loadPlanCommits(repoRows) {
    var repo = asArray(repoRows)[0];
    var repoId = val(repo, "id");
    if (!repoId) return Promise.resolve([]);
    return endpoint.schema("bundle").table("commit").rows({
        where: { name: "repository_id", op: "=", value: repoId }
    });
}

function load() {
    w.find(".loader").show();
    w.find(".plan-layout").hide();
    w.find(".no-plans").hide();
    w.find(".load-error").hide().text("");

    Promise.all([
        endpoint.schema("companion").table("plan").rows({}),
        endpoint.schema("companion").view("plan_step_with_review").rows({}),
        endpoint.schema("companion").table("plan_review").rows({}),
        endpoint.schema("ai").table("agent").rows({}),
        endpoint.schema("bundle").table("repository").rows({ where: { name: "name", op: "=", value: PLAN_BUNDLE } })
    ]).then(function(results) {
        _plans = asArray(results[0]);
        _steps = asArray(results[1]);
        _reviews = asArray(results[2]);
        _agents = {};
        asArray(results[3]).forEach(function(agent) {
            _agents[val(agent, "id")] = val(agent, "name");
        });
        return loadPlanCommits(results[4]);
    }).then(function(commits) {
        buildRowAuthors(commits);
        w.find(".loader").hide();
        render();
    }).catch(function(e) {
        w.find(".loader").hide();
        w.find(".load-error").text("Error: " + e).show();
        console.error("companion_plan_viewer error:", e);
    });
}

w.on("click", ".filter", function() {
    w.find(".filter").removeClass("active");
    $(this).addClass("active");
    _filter = $(this).data("status");
    render();
});

w.on("click", ".plan-item", function() {
    _selectedPlanId = $(this).data("id");
    render();
});

w.find("button.refresh").click(function() { load(); });
load();
